// SIE (Securities Industry Essentials) exam — practice question bank
// Same quiz-item shape as data/curriculum.js lesson quizzes: {q, a, explanation, options:[{text, explanation}]}
// plus an id and a section tag mapping to the four SIE_BLUEPRINT sections in sie.js.
//
// section values: "capital-markets" | "products-risks" | "trading-accounts" | "regulatory"
// Distribution targets blueprint weight: capital-markets ~16%, products-risks ~44%,
// trading-accounts ~31%, regulatory ~9%.
//
// The bank is assembled from a core of 146 items written first (BASE, below) plus four
// per-section expansion files folded in at the end. The split is authorship history, not
// a semantic distinction: SIE_BANK is one flat array and nothing downstream knows or cares
// which file an item came from. Kept as separate modules because each section file is large
// enough to be reviewed on its own, and a per-section accuracy review is the whole point.
//
// Section counts are load-bearing. lib/exam/blueprint.js draws a 75-question form as
// 12/33/23/7 across sections 1-4, so N distinct full forms needs N x that in every section.
// See test/cert-sie-bank.test.js, which asserts the distinct-form count against the real
// blueprint rather than against a number hardcoded here.

import { SIE_BANK_CAPITAL_MARKETS } from "./sie-bank-capital-markets.js";
import { SIE_BANK_PRODUCTS_RISKS } from "./sie-bank-products-risks.js";
import { SIE_BANK_TRADING_ACCOUNTS } from "./sie-bank-trading-accounts.js";
import { SIE_BANK_REGULATORY } from "./sie-bank-regulatory.js";
import { SIE_EXPANSION } from "./expansion/index.js";

