    q: "For recordkeeping purposes, a 'customer complaint' that a firm must capture in its complaint records is best described as:",
    a: "Any written statement from a customer alleging a grievance in the handling of their account",
    explanation: "The recordkeeping obligation is triggered by a written grievance about the firm or its associated persons in handling the customer's account — it isn't limited to complaints that result in a settlement, and a merely verbal remark to a principal doesn't by itself create the same documented record.",
