    explanation: "CAT requires exchanges and broker-dealers to report detailed, time-stamped order and trade data — from origination through execution — to a single repository, letting the SEC and SROs reconstruct trading activity across markets to detect manipulation, investigate unusual events, and conduct surveillance. It is a reporting and surveillance system, not a settlement, insurance, or execution-price mechanism.",
