    explanation: "Special tax bonds are backed by one particular, earmarked tax source (for example, a fuel or excise tax) rather than the project revenues used to back a typical revenue bond or the broad taxing authority behind a general obligation bond. The designated tax stands in place of the issuer's general taxing power.",
