    explanation: "Resigning or being terminated does not erase FINRA's ability to pursue misconduct that happened while the person was registered — FINRA retains jurisdiction for a defined window after the person leaves the industry specifically so that conduct occurring under its watch can still be investigated and disciplined. During that window FINRA may still investigate and take action on the prior conduct.",
