    explanation: "Rule 2210(b)(1)(A) requires an appropriately qualified registered principal to approve each retail communication before the earlier of its use or filing. Rule 2210(b)(3) imposes no such blanket pre-approval on institutional communications: the firm must instead establish written procedures for principal review that are appropriate to its business, size, structure and customers — and where those procedures do not call for review before first use, they must provide for education and training of associated persons, documentation of that training, and surveillance and follow-up. The firm must maintain written supervisory procedures for reviewing institutional communications.",
